cardCss:
.dc-act { width:44px;height:44px;border-radius:9999px;display:inline-flex;align-items:center;justify-content:center;background:var(--action-btn-bg,#eef2f7);color:var(--ink-3,#64748b);border:none;cursor:pointer;transition:all .18s ease;font-size:18px; }
.dc-act:hover { background:var(--chs-red,#dc2626);color:#fff;transform:translateY(-2px);box-shadow:0 4px 12px rgba(220,38,38,.25); }
.dc-act:active { transform:scale(.9); }
.dc-act.is-active { background:var(--chs-red,#dc2626);color:#fff; }
.dc-act.act-mark.is-active { background:var(--unknown,#f43f5e);color:#fff; }
.dc-act.act-fav.is-active { background:var(--amber,#d97706);color:#fff; }
.dc-scroll { scrollbar-width:thin;scrollbar-color:var(--line) transparent; }
.dc-scroll::-webkit-scrollbar { width:8px; }
.dc-scroll::-webkit-scrollbar-thumb { background:var(--line);border-radius:8px; }
body.dark-mode .dc-act { background:#1f2937;color:#cbd5e1; }
body.dark-mode .dc-act:hover,body.dark-mode .dc-act.is-active { color:#fff; }

.chs-word { color: var(--ink,#1e293b); font-weight:800; letter-spacing:.04em; }
.chs-pinyin { color: var(--chs-red,#dc2626); font-weight:600; }
.chs-tag { background: var(--chs-red,#dc2626); color:#fff; }
.chs-trad { color: var(--ink-2,#475569); }
.chs-def { color: var(--ink-2,#475569); }
.dc-card.chs { border-left: 4px solid var(--chs-red,#dc2626); }
.dc-card.chs.highlighted { border-left-color: var(--unknown,#f43f5e); background: #fef6f3; }
body.dark-mode .dc-card.chs.highlighted { background: #2a1417; }
.chs-def-panel { background: rgba(220,38,38,.05); border-radius:12px; padding:10px 12px; }

cardJs:
(function () {
    'use strict';
    function esc(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    function splitDef(t) {
        if (t == null) return [];
        var s = String(t);
        var parts = s.split('/');
        var out = [];
        parts.forEach(function (p) {
            p = p.trim();
            if (p) out.push(p);
        });
        return out;
    }
    window.cardTemplate = {
        name: 'Chinese HSK (汉字)',
        fields: [
            { key: 'word', label: '汉字', hideable: false },
            { key: 'pinyin', label: '拼音' },
            { key: 'part_of_speech', label: '词性' },
            { key: 'traditional', label: '繁体' },
            { key: 'definition', label: '英文释义' },
            { key: 'definition_source', label: '释义来源' },
            { key: 'level', label: 'HSK等级' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(k) { return hidden.has && hidden.has(k); }
            function h(k, html) { return isHidden(k) ? '' : html; }

            var markActive = data.is_unknown === 1 ? ' is-active' : '';
            var favActive = data.is_favorite === 1 ? ' is-active' : '';

            var html = '';
            // CRITICAL: root MUST carry data-card-id or init() never binds and all buttons die.
            html += '<div class="dc-card chs flex flex-col max-h-[560px] bg-[var(--card-bg)] text-[var(--ink)] border border-[var(--line)] rounded-2xl p-4 shadow-sm mb-4'
                + (data.is_unknown === 1 ? ' highlighted' : '') + '" data-card-id="' + data.id + '">';

            // Header: identity left, 3 actions right (consistent placement across templates)
            html += '<div class="flex items-start justify-between gap-3 mb-3 shrink-0">';
            html += '<div class="flex items-baseline gap-2 flex-wrap min-w-0">';
            html += '<span class="ew-index text-xs font-semibold" style="color:var(--ink-3,#64748b)">' + String(data.current_order).padStart(2, '0') + '</span>';
            html += h('word', '<span class="chs-word text-5xl" style="font-size:calc(48px*var(--card-font-scale,1))">' + esc(d.word) + '</span>');
            html += '</div>';
            // action buttons (top-right)
            html += '<div class="flex items-center gap-2 shrink-0">';
            html += '<button class="dc-act act-play" data-action="play" data-tooltip="发音"><i class="fa-solid fa-volume-high"></i></button>';
            html += '<button class="dc-act act-mark' + markActive + '" data-action="mark" data-tooltip="标记"><i class="fa-solid fa-bookmark"></i></button>';
            html += '<button class="dc-act act-fav' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="fa-' + (data.is_favorite === 1 ? 'solid' : 'regular') + ' fa-star"></i></button>';
            html += '</div>';
            html += '</div>';

            // meta row: pinyin + part of speech + traditional + level (all on ONE line)
            var trad = d.traditional;
            html += '<div class="flex items-center gap-2 flex-wrap mb-2">';
            html += h('pinyin', '<span class="chs-pinyin text-lg" style="font-size:calc(20px*var(--card-font-scale,1))">' + esc(d.pinyin) + '</span>');
            html += h('part_of_speech', (d.part_of_speech ? '<span class="chs-tag text-xs px-2 py-0.5 rounded-full" style="font-size:calc(12px*var(--card-font-scale,1))">' + esc(d.part_of_speech) + '</span>' : ''));
            html += h('traditional', (trad && trad !== d.word ? '<span class="chs-trad text-sm">繁：' + esc(trad) + '</span>' : ''));
            html += h('level', (d.level != null ? '<span class="text-xs px-2 py-0.5 rounded-full" style="color:var(--ink-3,#64748b);border:1px solid var(--line)">HSK ' + esc(d.level) + '</span>' : ''));
            html += '</div>';

            // definition (split on "/" into lines) + source credit inside the tinted panel (bottom-right, English only)
            html += h('definition', (function () {
                var items = splitDef(d.definition);
                if (!items.length) return '';
                var out = '<div class="dc-scroll overflow-y-auto space-y-1 chs-def-panel" style="font-size:calc(15px*var(--card-font-scale,1));line-height:1.7;color:var(--ink-2,#475569)">';
                items.forEach(function (t) { out += '<div>' + esc(t) + '</div>'; });
                var src = d.definition_source;
                if (src && !isHidden('definition_source')) {
                    out += '<div class="chs-src text-right mt-1" style="font-size:calc(11px*var(--card-font-scale,1));color:var(--ink-3,#64748b)">Source: ' + esc(src) + '</div>';
                }
                out += '</div>';
                return out;
            })());

            html += '</div>';
            return html;
        },
        init: function (cardElement, cardData, api) {
            var pb = cardElement.querySelector('[data-action="play"]');
            if (pb) pb.addEventListener('click', function (e) {
                e.stopPropagation();
                var d = (api.getCardData ? api.getCardData() : cardData).data || {};
                var w = d.word;
                if (w) api.playAudio(w);   // reads the CHINESE CHARACTERS (zh voice), never pinyin
                api.track('audio_play');
            });
            var mb = cardElement.querySelector('[data-action="mark"]');
            if (mb) mb.addEventListener('click', function (e) {
                e.stopPropagation();
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var fb = cardElement.querySelector('[data-action="favorite"]');
            if (fb) fb.addEventListener('click', function (e) {
                e.stopPropagation();
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
        }
    };
})();
